window.FA_DECKS={"income":{"unit":"Careers & Income","cards":[{"id":"income-card-1","skillId":"income-skill-02","front":"Gross pay","back":"Total earnings before any taxes or deductions are taken out","example":"A $52,000 salary is $2,000 gross per biweekly paycheck.","watch":""},{"id":"income-card-2","skillId":"income-skill-02","front":"Net pay","back":"The amount actually received after all taxes and deductions","example":"A $2,000 gross check becomes a $1,540 direct deposit.","watch":"Students often think a salary figure is what lands in the bank."},{"id":"income-card-3","skillId":"income-skill-01","front":"Salary","back":"A fixed annual amount of pay, divided across pay periods regardless of exact hours worked","example":"A $48,000 salary paid semimonthly is $2,000 per check.","watch":""},{"id":"income-card-4","skillId":"income-skill-01","front":"Hourly wage","back":"Pay based on the number of hours worked","example":"$18.50 per hour × 40 hours = $740 for a week.","watch":""},{"id":"income-card-5","skillId":"income-skill-01","front":"Overtime","back":"Hours beyond 40 in a workweek, usually paid at 1.5 times the regular rate for hourly workers covered by federal law","example":"6 overtime hours at $20/hour earn 6 × $30 = $180.","watch":""},{"id":"income-card-6","skillId":"income-skill-01","front":"Commission","back":"Pay calculated as a percent of sales made","example":"A 4% commission on $60,000 of sales earns $2,400.","watch":""},{"id":"income-card-7","skillId":"income-skill-01","front":"Benefits","back":"Non-wage compensation such as health insurance, retirement matching, and paid time off","example":"An employer paying $500/month toward health insurance adds $6,000 of yearly value.","watch":""},{"id":"income-card-8","skillId":"income-skill-02","front":"Pay period","back":"The span of time covered by one paycheck (weekly, biweekly, semimonthly, or monthly)","example":"Biweekly gives 26 pay periods per year.","watch":""},{"id":"income-card-9","skillId":"income-skill-03","front":"Deduction","back":"An amount subtracted from gross pay, such as taxes, insurance premiums, or retirement contributions","example":"$62 for health insurance listed on a pay stub.","watch":""},{"id":"income-card-10","skillId":"income-skill-03","front":"Year-to-date (YTD)","back":"The running total of an item from January 1 through the current pay period","example":"YTD gross of $24,000 after the 12th biweekly paycheck of $2,000.","watch":""},{"id":"income-card-11","skillId":"income-skill-04","front":"FICA","back":"Federal payroll taxes for Social Security (6.2%) and Medicare (1.45%), totaling 7.65% for most employees","example":"$1,000 gross → $62.00 + $14.50 = $76.50 FICA.","watch":""},{"id":"income-card-12","skillId":"income-skill-04","front":"Withholding","back":"Income tax an employer takes from each paycheck and sends to the government in advance","example":"Federal withholding of $148 on a biweekly check.","watch":""},{"id":"income-card-13","skillId":"income-skill-04","front":"Taxable income","back":"Income that is subject to income tax after subtracting allowed amounts such as the standard deduction and pre-tax contributions","example":"$45,000 − $15,000 standard deduction = $30,000 taxable (course model).","watch":""},{"id":"income-card-14","skillId":"income-skill-04","front":"Standard deduction","back":"A flat amount of income that is not taxed, available to filers who do not itemize","example":"The Course Tax Table uses $15,000 for a single filer.","watch":""},{"id":"income-card-15","skillId":"income-skill-04","front":"Marginal tax rate","back":"The tax rate applied to the last (next) dollar of taxable income","example":"Taxable income of $60,000 is in the 22% bracket, so the next dollar is taxed 22%.","watch":"Moving into a higher bracket does NOT raise the tax on all income."},{"id":"income-card-16","skillId":"income-skill-04","front":"Effective tax rate","back":"Total tax divided by income; the average rate actually paid","example":"$5,160 tax on $45,000 → about 11.5%.","watch":""},{"id":"income-card-17","skillId":"income-skill-02","front":"Pre-tax deduction","back":"A deduction taken before income tax is calculated, which lowers taxable income","example":"A 5% 401(k) contribution on $50,000 lowers taxable wages by $2,500.","watch":""},{"id":"income-card-18","skillId":"income-skill-04","front":"W-4 form","back":"The form an employee gives an employer to determine how much federal income tax to withhold","example":"Completing a W-4 on the first day of a new job.","watch":""},{"id":"income-card-x1","skillId":"income-skill-01","front":"Hourly → annual","back":"rate × hours per week × weeks worked (+ overtime at 1.5 × rate)","example":"$20 × 40 × 52 = $41,600","watch":"","kind":"formula"},{"id":"income-card-x2","skillId":"income-skill-01","front":"Total compensation","back":"Salary or wages + benefits (insurance, match, paid time off) − costs of working (commute, required equipment).","example":"","watch":"","kind":"principle"},{"id":"income-card-x3","skillId":"income-skill-03","front":"Pay stub columns","back":"“This period” shows the current check; “YTD” is the running total since January 1.","example":"","watch":"","kind":"document"},{"id":"income-card-x4","skillId":"income-skill-04","front":"Marginal vs. effective rate","back":"Marginal = rate on the next dollar; effective = total tax ÷ income. Effective is always lower in a progressive system.","example":"","watch":"","kind":"relationship"},{"id":"income-card-x5","skillId":"income-skill-04","front":"FICA","back":"Social Security 6.2% + Medicare 1.45% = 7.65% of wages.","example":"$1,500 × 0.0765 = $114.75","watch":"","kind":"formula"},{"id":"income-card-x6","skillId":"income-skill-02","front":"Pre-tax deduction","back":"Lowers taxable income, so net pay drops by less than the amount contributed.","example":"","watch":"","kind":"relationship"}]},"budgeting":{"unit":"Budgeting & Spending","cards":[{"id":"budgeting-card-1","skillId":"budgeting-skill-01","front":"Budget","back":"A plan that assigns expected income to spending, saving, and debt payments for a period of time","example":"Ana plans $1,200 for rent, $350 for groceries, and $200 for savings from her $2,600 monthly take-home pay.","watch":"A budget is a restriction rather than a plan you control."},{"id":"budgeting-card-2","skillId":"budgeting-skill-01","front":"Cash flow","back":"Money coming in minus money going out during a period","example":"Income of $2,900 and expenses of $3,050 produce a −$150 monthly result.","watch":""},{"id":"budgeting-card-3","skillId":"budgeting-skill-01","front":"Surplus","back":"The amount left over when income is greater than expenses","example":"After every bill is paid, Theo has $240 left this month.","watch":""},{"id":"budgeting-card-4","skillId":"budgeting-skill-01","front":"Deficit","back":"The shortfall when expenses are greater than income","example":"Expenses of $2,480 against income of $2,300 leave a $180 gap covered by a credit card.","watch":""},{"id":"budgeting-card-5","skillId":"budgeting-skill-01","front":"Net income (take-home pay)","back":"Pay remaining after taxes and other deductions; the amount a budget should be built on","example":"A $1,650 biweekly gross check becomes a $1,282 deposit after withholding.","watch":"Students often budget with gross pay, overstating what they can spend."},{"id":"budgeting-card-6","skillId":"budgeting-skill-01","front":"Sinking fund","back":"Money set aside each month for a known, irregular future expense","example":"Saving $90 a month so a $1,080 annual car-insurance bill is already covered when it arrives.","watch":""},{"id":"budgeting-card-7","skillId":"budgeting-skill-02","front":"Fixed expense","back":"A cost that stays the same amount each period","example":"A $1,325 rent payment that is identical every month under a lease.","watch":""},{"id":"budgeting-card-8","skillId":"budgeting-skill-02","front":"Variable expense","back":"A cost whose amount changes from period to period","example":"Grocery spending of $312, $367, and $341 in three consecutive months.","watch":""},{"id":"budgeting-card-9","skillId":"budgeting-skill-02","front":"Discretionary expense","back":"Spending on wants that could be reduced or eliminated without affecting basic needs","example":"Concert tickets, takeout meals, and a second streaming service.","watch":""},{"id":"budgeting-card-10","skillId":"budgeting-skill-02","front":"Essential expense (need)","back":"Spending required for basic living or to keep earning income","example":"Rent, basic groceries, utilities, and transportation to work.","watch":""},{"id":"budgeting-card-11","skillId":"budgeting-skill-02","front":"50/30/20 guideline","back":"A starting-point plan that directs about 50% of take-home pay to needs, 30% to wants, and 20% to savings and extra debt payments","example":"With $3,000 take-home pay: about $1,500 needs, $900 wants, $600 savings.","watch":"It is a rule everyone must follow; in high-cost areas needs often exceed 50%."},{"id":"budgeting-card-12","skillId":"budgeting-skill-03","front":"Emergency fund","back":"Savings reserved for unexpected expenses or income loss, often targeted at 3–6 months of essential expenses","example":"Keeping $6,600 in savings when essential expenses are $2,200 per month (3 months).","watch":""},{"id":"budgeting-card-13","skillId":"budgeting-skill-03","front":"Financial constraint","back":"A limit, such as income or a savings target, that restricts which spending choices are possible","example":"Rent must be at most 30% of gross income: r ≤ 0.30 × 4,000.","watch":""},{"id":"budgeting-card-14","skillId":"budgeting-skill-03","front":"Savings goal","back":"A specific amount of money to accumulate by a target date","example":"$2,400 for a used-car down payment within 12 months requires $200 per month.","watch":""},{"id":"budgeting-card-15","skillId":"budgeting-skill-04","front":"Opportunity cost","back":"The value of the next-best alternative given up when making a choice","example":"Spending $1,200 a year on takeout lunches means not putting that $1,200 toward an emergency fund.","watch":"Opportunity cost is only money; it can also be time or flexibility."},{"id":"budgeting-card-16","skillId":"budgeting-skill-04","front":"Unit price","back":"The cost per single unit (ounce, item, load) used to compare package sizes fairly","example":"$8.99 for 24 oz is about $0.375 per ounce.","watch":""},{"id":"budgeting-card-17","skillId":"budgeting-skill-04","front":"Impulse purchase","back":"An unplanned purchase made on the spot, often influenced by marketing or emotion","example":"Buying a $45 gadget near the checkout that was not on the list.","watch":""},{"id":"budgeting-card-18","skillId":"budgeting-skill-04","front":"Buy now, pay later (BNPL)","back":"A short-term financing plan that splits a purchase into installments, sometimes with late fees or interest","example":"A $240 jacket paid in four $60 installments every two weeks.","watch":"BNPL is “free money”; missed payments can add fees and stack up across several plans."},{"id":"budgeting-card-19","skillId":"budgeting-skill-04","front":"Sales tax","back":"A percent of the purchase price collected by the state at the time of sale","example":"A $40 item with 6.25% sales tax costs $42.50.","watch":""},{"id":"budgeting-card-x1","skillId":"budgeting-skill-01","front":"Biweekly pay → monthly","back":"Multiply the paycheck by 26, then divide by 12.","example":"$1,240 × 26 ÷ 12 = $2,686.67","watch":"Not × 2 — that misses two paychecks a year.","kind":"formula"},{"id":"budgeting-card-x2","skillId":"budgeting-skill-01","front":"Pay yourself first","back":"Move savings out on payday before spending, so saving is a planned expense rather than leftovers.","example":"","watch":"","kind":"principle"},{"id":"budgeting-card-x3","skillId":"budgeting-skill-01","front":"Bank statement: what to scan first","back":"Total deposits, total withdrawals, ending balance, recurring charges, and fees.","example":"","watch":"","kind":"document"},{"id":"budgeting-card-x4","skillId":"budgeting-skill-02","front":"Fixed vs. variable vs. need vs. want","back":"Two separate questions: does the amount change? Is it required? A subscription is a fixed want; groceries are a variable need.","example":"","watch":"","kind":"relationship"},{"id":"budgeting-card-x5","skillId":"budgeting-skill-03","front":"Rounding in the safe direction","back":"Round hours and months UP; round maximum spending DOWN.","example":"72.6 hours → 73 hours","watch":"","kind":"principle"},{"id":"budgeting-card-x6","skillId":"budgeting-skill-04","front":"Break-even uses","back":"Fixed cost ÷ savings per use, rounded up.","example":"$35 membership ÷ $8 per visit → 5 visits","watch":"","kind":"formula"},{"id":"budgeting-card-x7","skillId":"budgeting-skill-04","front":"Total cost beats monthly payment","back":"Compare what you pay in total, including fees and interest — not the size of each payment.","example":"","watch":"","kind":"principle"}]},"banking":{"unit":"Banking & Saving","cards":[{"id":"banking-card-1","skillId":"banking-skill-01","front":"Checking account","back":"A bank account for everyday spending through a debit card, transfers, and checks","example":"Paychecks are deposited into checking and rent is paid from it.","watch":""},{"id":"banking-card-2","skillId":"banking-skill-03","front":"Savings account","back":"An account designed for holding money and earning interest, with fewer transactions than checking","example":"An emergency fund kept in a 4.00% APY savings account.","watch":""},{"id":"banking-card-3","skillId":"banking-skill-01","front":"Overdraft fee","back":"A fee charged when a transaction is paid even though the account does not have enough money","example":"A $4.50 coffee triggers a $35 overdraft fee.","watch":"Overdraft “protection” sounds free but often carries a fee for each transaction."},{"id":"banking-card-4","skillId":"banking-skill-01","front":"Monthly maintenance fee","back":"A recurring charge for keeping an account open, often waived by meeting a minimum balance or direct-deposit requirement","example":"$12 per month unless the balance stays above $1,500.","watch":""},{"id":"banking-card-5","skillId":"banking-skill-01","front":"Minimum balance requirement","back":"The lowest balance an account must keep to avoid a fee or earn a stated rate","example":"The fee is waived only if the daily balance never drops below $500.","watch":""},{"id":"banking-card-6","skillId":"banking-skill-01","front":"Out-of-network ATM fee","back":"A charge for using an ATM not owned by your bank; often charged by both banks","example":"$3.00 from the ATM owner + $2.50 from your bank.","watch":""},{"id":"banking-card-7","skillId":"banking-skill-02","front":"Principal","back":"The original amount of money deposited or borrowed, on which interest is calculated","example":"Depositing $2,000 into a CD.","watch":""},{"id":"banking-card-8","skillId":"banking-skill-02","front":"Simple interest","back":"Interest calculated only on the original principal: I = Prt","example":"$2,000 at 3% for 2 years earns $120.","watch":""},{"id":"banking-card-9","skillId":"banking-skill-03","front":"Compound interest","back":"Interest calculated on the principal plus previously earned interest","example":"$1,000 at 5% compounded yearly is $1,102.50 after 2 years.","watch":""},{"id":"banking-card-10","skillId":"banking-skill-03","front":"APY (annual percentage yield)","back":"The actual yearly rate of return including the effect of compounding","example":"4.00% compounded monthly gives an APY of about 4.07%.","watch":"APY and APR are not the same; APY includes compounding."},{"id":"banking-card-11","skillId":"banking-skill-03","front":"Certificate of deposit (CD)","back":"A savings product that pays a fixed rate for a set term, usually with a penalty for early withdrawal","example":"A 12-month CD at 4.25% with a 3-month interest penalty for early withdrawal.","watch":""},{"id":"banking-card-12","skillId":"banking-skill-03","front":"FDIC/NCUA insurance","back":"Federal protection of deposits at insured banks and credit unions, up to $250,000 per depositor per ownership category","example":"If an insured bank fails, deposits up to the limit are protected.","watch":""},{"id":"banking-card-13","skillId":"banking-skill-03","front":"Credit union","back":"A member-owned, not-for-profit financial cooperative that offers banking services","example":"Joining a teachers’ credit union with a $5 membership share.","watch":""},{"id":"banking-card-14","skillId":"banking-skill-04","front":"Bank statement","back":"A periodic summary of an account showing the beginning balance, deposits, withdrawals, fees, interest, and ending balance","example":"A monthly PDF statement from your bank’s app.","watch":""},{"id":"banking-card-15","skillId":"banking-skill-04","front":"Reconcile","back":"To compare your own records with the bank statement and explain any differences","example":"Matching your register after accounting for a check that has not cleared.","watch":""},{"id":"banking-card-16","skillId":"banking-skill-04","front":"Outstanding transaction","back":"A transaction you recorded that has not yet appeared on the bank statement","example":"A check written on the 29th that clears next month.","watch":""},{"id":"banking-card-17","skillId":"banking-skill-01","front":"Direct deposit","back":"An electronic payment of wages straight into a bank account","example":"Paychecks arrive every other Friday by direct deposit.","watch":""},{"id":"banking-card-18","skillId":"banking-skill-03","front":"Liquidity","back":"How quickly and easily money can be accessed without losing value","example":"A savings account is more liquid than a 5-year CD.","watch":""},{"id":"banking-card-x1","skillId":"banking-skill-02","front":"Simple interest","back":"I = Prt (P principal, r annual rate as a decimal, t years)","example":"$800 × 0.03 × 2 = $48","watch":"","kind":"formula"},{"id":"banking-card-x2","skillId":"banking-skill-03","front":"Compound amount","back":"A = P(1 + r ÷ n)^(nt)","example":"$1,000 at 4% monthly for 5 yr ≈ $1,221.00","watch":"","kind":"formula"},{"id":"banking-card-x3","skillId":"banking-skill-03","front":"APR vs. APY","back":"APR is the stated yearly rate; APY includes compounding, so APY ≥ APR.","example":"","watch":"","kind":"relationship"},{"id":"banking-card-x4","skillId":"banking-skill-03","front":"Liquidity tradeoff","back":"Higher fixed rates (CDs) usually mean less access to your money.","example":"","watch":"","kind":"principle"},{"id":"banking-card-x5","skillId":"banking-skill-04","front":"Statement red flags","back":"Unknown merchants, duplicate charges, fees you did not expect, and missing deposits.","example":"","watch":"","kind":"document"},{"id":"banking-card-x6","skillId":"banking-skill-04","front":"Reconciling","back":"Statement balance − outstanding withdrawals + deposits in transit = your true balance.","example":"","watch":"","kind":"formula"}]},"credit":{"unit":"Credit Cards & Debt","cards":[{"id":"credit-card-1","skillId":"credit-skill-01","front":"APR (annual percentage rate)","back":"The yearly cost of borrowing expressed as a percent, used to compute interest on a balance","example":"A card with 24% APR charges about 2% per month.","watch":"APR is not charged once a year; it is divided into periodic (monthly or daily) rates."},{"id":"credit-card-2","skillId":"credit-skill-01","front":"Periodic rate","back":"The APR divided into the rate for one billing period or day","example":"21% APR ÷ 12 = 1.75% per month.","watch":""},{"id":"credit-card-3","skillId":"credit-skill-01","front":"Balance","back":"The amount owed on an account at a given time","example":"A $1,240 balance after this month’s purchases.","watch":""},{"id":"credit-card-4","skillId":"credit-skill-01","front":"Grace period","back":"The time between the end of a billing cycle and the due date during which new purchases are not charged interest if the full balance is paid","example":"Paying the full statement balance by the due date avoids interest on purchases.","watch":""},{"id":"credit-card-5","skillId":"credit-skill-01","front":"Average daily balance","back":"A method of computing interest by averaging the balance owed on each day of the billing cycle","example":"$800 for 10 days and $1,100 for 20 days → about $1,000 average.","watch":""},{"id":"credit-card-6","skillId":"credit-skill-02","front":"Minimum payment","back":"The smallest payment required by the due date to keep the account in good standing","example":"1% of the balance plus interest, at least $25.","watch":"The minimum payment is not a recommended payment; paying only it keeps you in debt for years."},{"id":"credit-card-7","skillId":"credit-skill-04","front":"Credit limit","back":"The maximum balance a lender allows on a credit account","example":"A $3,000 limit on a first credit card.","watch":""},{"id":"credit-card-8","skillId":"credit-skill-04","front":"Credit utilization","back":"The percent of available revolving credit currently being used","example":"$900 balance ÷ $3,000 limit = 30% utilization.","watch":""},{"id":"credit-card-9","skillId":"credit-skill-04","front":"Credit score","back":"A number (commonly 300–850) summarizing credit risk based on payment history, amounts owed, length of history, new credit, and credit mix","example":"On-time payments and low utilization help raise a score.","watch":""},{"id":"credit-card-10","skillId":"credit-skill-04","front":"Credit report","back":"A record of a person’s credit accounts and payment history kept by credit bureaus","example":"You can request free reports from each of the three nationwide bureaus.","watch":""},{"id":"credit-card-11","skillId":"credit-skill-04","front":"Late fee","back":"A charge for paying less than the minimum by the due date","example":"A $35 fee plus possible penalty APR.","watch":""},{"id":"credit-card-12","skillId":"credit-skill-03","front":"Debt avalanche","back":"A repayment strategy that sends extra money to the debt with the highest interest rate first","example":"Extra $100 goes to a 27% card before a 9% loan.","watch":""},{"id":"credit-card-13","skillId":"credit-skill-03","front":"Debt snowball","back":"A repayment strategy that sends extra money to the smallest balance first for quick wins","example":"Pay off the $300 store card first, then roll that payment into the next debt.","watch":""},{"id":"credit-card-14","skillId":"credit-skill-03","front":"Balance transfer","back":"Moving a balance to another card, often at a low promotional rate with a transfer fee","example":"0% for 15 months with a 3% fee.","watch":""},{"id":"credit-card-15","skillId":"credit-skill-04","front":"Cash advance","back":"Withdrawing cash using a credit card, usually with a fee, a higher APR, and no grace period","example":"$200 advance with a $10 fee and 29.99% APR starting immediately.","watch":""},{"id":"credit-card-16","skillId":"credit-skill-02","front":"Revolving credit","back":"Credit that can be borrowed, repaid, and borrowed again up to a limit","example":"A credit card, unlike a car loan.","watch":""},{"id":"credit-card-x1","skillId":"credit-skill-01","front":"Monthly card interest","back":"balance × APR ÷ 12 (or average daily balance × APR ÷ 365 × days)","example":"$2,000 × 0.24 ÷ 12 = $40","watch":"","kind":"formula"},{"id":"credit-card-x2","skillId":"credit-skill-02","front":"Minimum payment trap","back":"Minimums barely exceed interest, so the balance shrinks slowly and total interest balloons.","example":"","watch":"","kind":"principle"},{"id":"credit-card-x3","skillId":"credit-skill-03","front":"Avalanche vs. snowball","back":"Avalanche saves the most interest; snowball gives quicker wins. Both beat minimum payments.","example":"","watch":"","kind":"relationship"},{"id":"credit-card-x4","skillId":"credit-skill-04","front":"Credit card statement must-reads","back":"New balance, minimum due, due date, APRs, interest charged, fees, and the minimum-payment warning box.","example":"","watch":"","kind":"document"},{"id":"credit-card-x5","skillId":"credit-skill-04","front":"Credit utilization","back":"Total balances ÷ total limits × 100; lower is better (many advisors suggest under 30%).","example":"","watch":"","kind":"formula"},{"id":"credit-card-x6","skillId":"credit-skill-04","front":"Credit score factors (approx. weights)","back":"Payment history ~35%, amounts owed ~30%, length ~15%, new credit ~10%, mix ~10% (FICO model).","example":"","watch":"","kind":"principle"}]},"borrowing":{"unit":"Auto Loans & Borrowing","cards":[{"id":"borrowing-card-1","skillId":"borrowing-skill-01","front":"Installment loan","back":"A loan repaid in equal scheduled payments over a fixed term","example":"A 60-month auto loan with $412.18 monthly payments.","watch":""},{"id":"borrowing-card-2","skillId":"borrowing-skill-02","front":"Loan term","back":"The length of time to repay a loan","example":"48 months vs. 72 months.","watch":""},{"id":"borrowing-card-3","skillId":"borrowing-skill-01","front":"Down payment","back":"Cash paid up front that reduces the amount borrowed","example":"$3,000 down on a $20,000 car means borrowing $17,000.","watch":""},{"id":"borrowing-card-4","skillId":"borrowing-skill-03","front":"Amortization","back":"Paying off a loan through regular payments that cover interest first and then principal","example":"Early payments are mostly interest; later payments are mostly principal.","watch":""},{"id":"borrowing-card-5","skillId":"borrowing-skill-03","front":"Amortization schedule","back":"A table showing each payment’s interest, principal, and remaining balance","example":"Month 1: interest $93.75, principal $318.43, balance $17,681.57.","watch":""},{"id":"borrowing-card-6","skillId":"borrowing-skill-04","front":"Finance charge","back":"The total dollar cost of credit, including interest and certain fees","example":"Total of payments $24,730.80 − amount financed $21,000 = $3,730.80.","watch":""},{"id":"borrowing-card-7","skillId":"borrowing-skill-04","front":"Total of payments","back":"The sum of all scheduled payments over the life of a loan","example":"$412.18 × 60 = $24,730.80.","watch":""},{"id":"borrowing-card-8","skillId":"borrowing-skill-04","front":"Upside down (negative equity)","back":"Owing more on a loan than the item is worth","example":"Owing $17,500 on a car worth $14,000.","watch":"Long loan terms make negative equity more likely because the balance falls slowly."},{"id":"borrowing-card-9","skillId":"borrowing-skill-04","front":"Depreciation","back":"The decline in an asset’s value over time","example":"A new car losing about 15–20% of its value in the first year.","watch":""},{"id":"borrowing-card-10","skillId":"borrowing-skill-02","front":"Lease","back":"A contract to use a vehicle for a set term and mileage in exchange for payments, without owning it","example":"36-month lease at $389/month with a 12,000-mile annual limit.","watch":""},{"id":"borrowing-card-11","skillId":"borrowing-skill-02","front":"Residual value","back":"The estimated value of a leased vehicle at the end of the lease","example":"58% of a $31,000 MSRP = $17,980.","watch":""},{"id":"borrowing-card-12","skillId":"borrowing-skill-02","front":"Money factor","back":"The lease version of an interest rate; multiply by 2,400 to estimate an equivalent APR","example":"0.0025 × 2,400 = 6% APR.","watch":""},{"id":"borrowing-card-13","skillId":"borrowing-skill-01","front":"Collateral","back":"An asset pledged to secure a loan that the lender can take if payments stop","example":"The car is collateral for an auto loan.","watch":""},{"id":"borrowing-card-14","skillId":"borrowing-skill-01","front":"Cosigner","back":"A person who agrees to repay a loan if the borrower does not","example":"A parent cosigns a teen’s first auto loan.","watch":""},{"id":"borrowing-card-15","skillId":"borrowing-skill-03","front":"Prepayment","back":"Paying more than the required payment to reduce the principal faster","example":"An extra $50 each month shortens a loan and cuts interest.","watch":""},{"id":"borrowing-card-16","skillId":"borrowing-skill-04","front":"Total cost of ownership","back":"All costs of having a vehicle over time: price or payments, interest, insurance, fuel, maintenance, fees, and lost value","example":"A cheaper car with high repair costs can cost more over 5 years.","watch":""},{"id":"borrowing-card-x1","skillId":"borrowing-skill-01","front":"Installment payment","back":"PMT = P·i ÷ (1 − (1 + i)^(−n)), i = APR ÷ 12, n = months","example":"","watch":"","kind":"formula"},{"id":"borrowing-card-x2","skillId":"borrowing-skill-03","front":"Amortization pattern","back":"Interest portion falls and principal portion rises each month; the payment stays the same.","example":"","watch":"","kind":"relationship"},{"id":"borrowing-card-x3","skillId":"borrowing-skill-04","front":"Finance charge","back":"Total of payments − amount financed","example":"","watch":"","kind":"formula"},{"id":"borrowing-card-x4","skillId":"borrowing-skill-02","front":"Lease payment (course model)","back":"Depreciation fee (cap cost − residual) ÷ months + rent charge (cap cost + residual) × money factor","example":"","watch":"","kind":"formula"},{"id":"borrowing-card-x5","skillId":"borrowing-skill-04","front":"Truth in Lending box","back":"APR, Finance Charge, Amount Financed, Total of Payments — compare these across offers.","example":"","watch":"","kind":"document"},{"id":"borrowing-card-x6","skillId":"borrowing-skill-04","front":"Negotiate in this order","back":"Price first, then APR, then term. Decide the payment last.","example":"","watch":"","kind":"principle"}]},"investing":{"unit":"Investing & Compound Growth","cards":[{"id":"investing-card-1","skillId":"investing-skill-01","front":"Compound growth","back":"Growth in which earnings are added to the balance and then earn returns themselves","example":"$1,000 growing 7% per year becomes $1,070, then $1,144.90.","watch":""},{"id":"investing-card-2","skillId":"investing-skill-01","front":"Rate of return","back":"The gain or loss on an investment over a period, expressed as a percent of the starting value","example":"A $500 investment worth $540 a year later returned 8%.","watch":""},{"id":"investing-card-3","skillId":"investing-skill-01","front":"Rule of 72","back":"A shortcut estimating years to double: 72 divided by the annual percent return","example":"At 6%, money doubles in about 72 ÷ 6 = 12 years.","watch":""},{"id":"investing-card-4","skillId":"investing-skill-02","front":"Recurring contribution","back":"A regular, repeated deposit into an investment, such as monthly","example":"$100 automatically invested on the 1st of every month.","watch":""},{"id":"investing-card-5","skillId":"investing-skill-02","front":"Future value","back":"The value of money or a series of payments at a future date given a rate of return","example":"FV of $200/month for 30 years at 6% ≈ $200,903.","watch":""},{"id":"investing-card-6","skillId":"investing-skill-02","front":"Dollar-cost averaging","back":"Investing a fixed dollar amount on a regular schedule regardless of price","example":"Buying more shares when prices are low and fewer when high with the same $150.","watch":""},{"id":"investing-card-7","skillId":"investing-skill-03","front":"Stock","back":"A share of ownership in a company whose value can rise or fall","example":"Owning 10 shares of a fictional company, Brightline Energy.","watch":""},{"id":"investing-card-8","skillId":"investing-skill-03","front":"Bond","back":"A loan to a government or company that pays interest and returns principal at maturity","example":"A 10-year bond paying 4% interest per year.","watch":""},{"id":"investing-card-9","skillId":"investing-skill-03","front":"Index fund","back":"A fund that holds the investments in a market index to match its performance at low cost","example":"A fund tracking a broad U.S. stock index.","watch":""},{"id":"investing-card-10","skillId":"investing-skill-03","front":"Expense ratio","back":"The yearly fee a fund charges, as a percent of the amount invested","example":"0.05% vs. 1.00% — on $50,000, that is $25 vs. $500 per year.","watch":""},{"id":"investing-card-11","skillId":"investing-skill-04","front":"Diversification","back":"Spreading money across many investments so that one loss has less impact","example":"Owning hundreds of companies through an index fund instead of one stock.","watch":""},{"id":"investing-card-12","skillId":"investing-skill-04","front":"Risk","back":"The possibility that actual returns differ from expected returns, including losing money","example":"A stock fund could fall 20% in a bad year.","watch":""},{"id":"investing-card-13","skillId":"investing-skill-04","front":"Volatility","back":"How much an investment’s value moves up and down over time","example":"Returns of +25%, −15%, +18% are more volatile than +5%, +4%, +6%.","watch":""},{"id":"investing-card-14","skillId":"investing-skill-04","front":"Time horizon","back":"How long until the money is needed","example":"Retirement in 45 years vs. a car purchase in 2 years.","watch":""},{"id":"investing-card-15","skillId":"investing-skill-04","front":"Risk tolerance","back":"A person’s ability and willingness to accept investment losses","example":"Someone who would sell in panic after a 10% drop has low risk tolerance.","watch":""},{"id":"investing-card-16","skillId":"investing-skill-03","front":"Real return","back":"Return after adjusting for inflation","example":"7% return with 3% inflation ≈ 3.9% real return.","watch":""},{"id":"investing-card-x1","skillId":"investing-skill-01","front":"Compound amount","back":"A = P(1 + r ÷ n)^(nt)","example":"","watch":"","kind":"formula"},{"id":"investing-card-x2","skillId":"investing-skill-02","front":"Future value of monthly deposits","back":"FV = PMT × ((1 + i)^N − 1) ÷ i, with i = r ÷ 12 and N = months","example":"","watch":"","kind":"formula"},{"id":"investing-card-x3","skillId":"investing-skill-01","front":"Rule of 72","back":"Years to double ≈ 72 ÷ (percent return)","example":"8% → 9 years","watch":"","kind":"formula"},{"id":"investing-card-x4","skillId":"investing-skill-04","front":"Risk and return","back":"Higher expected return usually means more volatility and possible losses.","example":"","watch":"","kind":"relationship"},{"id":"investing-card-x5","skillId":"investing-skill-04","front":"Match investments to time horizon","back":"Money needed soon → stable options; money for decades → diversified growth investments.","example":"","watch":"","kind":"principle"},{"id":"investing-card-x6","skillId":"investing-skill-04","front":"Losses need bigger gains","back":"A 50% loss needs a 100% gain to recover.","example":"","watch":"","kind":"relationship"}]},"housing":{"unit":"Housing: Rent or Buy","cards":[{"id":"housing-card-1","skillId":"housing-skill-01","front":"Lease (rental)","back":"A contract to rent a home for a set term at a set rent, with rules for both tenant and landlord","example":"A 12-month apartment lease at $1,650 per month.","watch":""},{"id":"housing-card-2","skillId":"housing-skill-01","front":"Security deposit","back":"Money paid to a landlord up front to cover damage or unpaid rent, generally refundable","example":"One month’s rent held until move-out.","watch":""},{"id":"housing-card-3","skillId":"housing-skill-01","front":"Renters insurance","back":"Insurance that covers a tenant’s belongings and liability, not the building","example":"$15 per month for $25,000 of personal property coverage.","watch":""},{"id":"housing-card-4","skillId":"housing-skill-02","front":"Mortgage","back":"A loan used to buy real estate, secured by the property","example":"A 30-year fixed mortgage at 6.75%.","watch":""},{"id":"housing-card-5","skillId":"housing-skill-02","front":"Principal and interest (P&I)","back":"The portion of a mortgage payment that repays the loan and pays interest","example":"P&I of $2,075 on a $320,000 loan at 6.75%.","watch":""},{"id":"housing-card-6","skillId":"housing-skill-03","front":"PITI","back":"Principal, interest, property taxes, and homeowners insurance — the full monthly housing payment","example":"$2,075 P&I + $380 tax + $125 insurance = $2,580.","watch":""},{"id":"housing-card-7","skillId":"housing-skill-02","front":"Down payment","back":"The part of a home’s price paid in cash at purchase","example":"20% of $350,000 = $70,000.","watch":""},{"id":"housing-card-8","skillId":"housing-skill-03","front":"Private mortgage insurance (PMI)","back":"Insurance protecting the lender, typically required when the down payment is under 20% on a conventional loan","example":"0.5–1% of the loan per year until enough equity is built.","watch":""},{"id":"housing-card-9","skillId":"housing-skill-03","front":"Closing costs","back":"Fees paid to complete a home purchase, often 2–5% of the price","example":"Appraisal, title insurance, origination fees.","watch":""},{"id":"housing-card-10","skillId":"housing-skill-03","front":"Property tax","back":"A local tax on real estate based on its assessed value","example":"1.2% of a $300,000 home = $3,600 per year.","watch":""},{"id":"housing-card-11","skillId":"housing-skill-04","front":"Equity","back":"The part of a home’s value that the owner truly owns: market value minus loan balance","example":"Worth $360,000 with a $290,000 mortgage → $70,000 equity.","watch":""},{"id":"housing-card-12","skillId":"housing-skill-04","front":"Appreciation","back":"An increase in the value of an asset over time","example":"A home rising 3% per year.","watch":"Home prices can also fall."},{"id":"housing-card-13","skillId":"housing-skill-04","front":"Opportunity cost (housing)","back":"The return given up by tying cash up in a down payment and closing costs instead of investing it","example":"$60,000 down could have earned about $3,000 a year at 5%.","watch":""},{"id":"housing-card-14","skillId":"housing-skill-01","front":"Front-end ratio","back":"Housing payment divided by gross monthly income; many lenders prefer about 28% or less","example":"$2,100 ÷ $7,500 = 28%.","watch":""},{"id":"housing-card-15","skillId":"housing-skill-01","front":"Debt-to-income ratio (DTI)","back":"All monthly debt payments, including housing, divided by gross monthly income","example":"($2,100 + $400 car) ÷ $7,500 ≈ 33%.","watch":""},{"id":"housing-card-16","skillId":"housing-skill-03","front":"HOA fee","back":"A monthly fee paid to a homeowners association for shared maintenance and amenities","example":"$250 per month for a townhouse community.","watch":""},{"id":"housing-card-17","skillId":"housing-skill-03","front":"Maintenance reserve","back":"Money set aside for home repairs; a common rule of thumb is 1–2% of home value per year","example":"1% of $350,000 = $3,500 per year.","watch":""},{"id":"housing-card-x1","skillId":"housing-skill-03","front":"PITI","back":"Principal + Interest + property Taxes + Insurance (+ PMI and HOA if applicable)","example":"","watch":"","kind":"formula"},{"id":"housing-card-x2","skillId":"housing-skill-01","front":"28/36 guideline","back":"Housing ≤ 28% of gross monthly income; all debts ≤ 36%.","example":"","watch":"","kind":"formula"},{"id":"housing-card-x3","skillId":"housing-skill-04","front":"Equity","back":"Market value − loan balance","example":"","watch":"","kind":"formula"},{"id":"housing-card-x4","skillId":"housing-skill-04","front":"Rent vs. buy depends on…","back":"Time horizon, price growth, rent growth, rates, transaction costs, and opportunity cost of the down payment.","example":"","watch":"","kind":"principle"},{"id":"housing-card-x5","skillId":"housing-skill-03","front":"Loan Estimate key lines","back":"Loan amount, interest rate, monthly P&I, projected payments with taxes/insurance, estimated closing costs, cash to close.","example":"","watch":"","kind":"document"},{"id":"housing-card-x6","skillId":"housing-skill-02","front":"15- vs. 30-year mortgage","back":"15-year: higher payment, lower rate, far less interest. 30-year: lower payment, more flexibility, more interest.","example":"","watch":"","kind":"relationship"}]},"insurance":{"unit":"Insurance & Risk","cards":[{"id":"insurance-card-1","skillId":"insurance-skill-01","front":"Premium","back":"The amount paid regularly to keep an insurance policy active, whether or not you file a claim","example":"$210 per month for a health plan.","watch":""},{"id":"insurance-card-2","skillId":"insurance-skill-01","front":"Deductible","back":"The amount you pay for covered costs before the insurer starts paying","example":"With a $1,000 auto deductible, a $3,200 repair costs you $1,000.","watch":""},{"id":"insurance-card-3","skillId":"insurance-skill-02","front":"Copay","back":"A fixed amount paid for a covered service, such as a doctor visit","example":"$30 per primary-care visit.","watch":""},{"id":"insurance-card-4","skillId":"insurance-skill-02","front":"Coinsurance","back":"Your percent share of covered costs after the deductible is met","example":"20% of a $4,000 bill after the deductible = $800.","watch":""},{"id":"insurance-card-5","skillId":"insurance-skill-02","front":"Out-of-pocket maximum","back":"The most you pay for covered care in a plan year; after that, the plan pays 100% of covered costs","example":"A $6,000 maximum caps costs even after a $90,000 surgery.","watch":""},{"id":"insurance-card-6","skillId":"insurance-skill-01","front":"Claim","back":"A formal request to an insurer to pay for a covered loss","example":"Filing a claim after a car accident.","watch":""},{"id":"insurance-card-7","skillId":"insurance-skill-04","front":"Policy limit","back":"The maximum amount an insurer will pay for a covered loss","example":"Liability coverage of $50,000 per person.","watch":""},{"id":"insurance-card-8","skillId":"insurance-skill-03","front":"Expected value","back":"The probability-weighted average of all possible outcomes","example":"10% chance of losing $2,000 → expected loss $200.","watch":""},{"id":"insurance-card-9","skillId":"insurance-skill-03","front":"Risk pooling","back":"Many people pay premiums so the losses of the few who have claims can be covered","example":"1,000 drivers each pay $1,200 so the company can pay the accident claims.","watch":""},{"id":"insurance-card-10","skillId":"insurance-skill-04","front":"Liability insurance","back":"Coverage that pays for injuries or damage you cause to others","example":"Auto liability pays the other driver’s repair bills.","watch":""},{"id":"insurance-card-11","skillId":"insurance-skill-04","front":"Collision coverage","back":"Auto coverage that pays to repair your own car after an accident, minus the deductible","example":"Optional on an older, low-value car.","watch":""},{"id":"insurance-card-12","skillId":"insurance-skill-04","front":"Comprehensive coverage","back":"Auto coverage for non-collision damage such as theft, hail, or hitting a deer","example":"A tree branch falls on a parked car.","watch":""},{"id":"insurance-card-13","skillId":"insurance-skill-02","front":"Network (in-network)","back":"Doctors and facilities that have agreed to a health plan’s negotiated prices","example":"Out-of-network visits may cost much more or not count toward the deductible.","watch":""},{"id":"insurance-card-14","skillId":"insurance-skill-01","front":"Health savings account (HSA)","back":"A tax-advantaged account paired with an eligible high-deductible health plan to save for medical costs","example":"Depositing $100 per month to cover a future deductible.","watch":""},{"id":"insurance-card-15","skillId":"insurance-skill-04","front":"Self-insure","back":"Choosing to cover a possible loss with your own savings instead of buying insurance","example":"Skipping collision on a $3,000 car and keeping savings for repairs.","watch":""},{"id":"insurance-card-16","skillId":"insurance-skill-04","front":"Risk tolerance (insurance)","back":"How much financial uncertainty a person can handle; affects deductible and coverage choices","example":"A person with $500 in savings should avoid a $5,000 deductible.","watch":""},{"id":"insurance-card-x1","skillId":"insurance-skill-02","front":"Out-of-pocket (health)","back":"min(bills, deductible) + coinsurance × (bills − deductible) + copays, capped at the out-of-pocket maximum","example":"","watch":"","kind":"formula"},{"id":"insurance-card-x2","skillId":"insurance-skill-01","front":"Premium vs. deductible","back":"Higher deductible → lower premium (you carry more risk); lower deductible → higher premium.","example":"","watch":"","kind":"relationship"},{"id":"insurance-card-x3","skillId":"insurance-skill-03","front":"Expected value","back":"EV = Σ (probability × outcome)","example":"0.05 × $8,000 = $400","watch":"","kind":"formula"},{"id":"insurance-card-x4","skillId":"insurance-skill-04","front":"Insure the catastrophes","back":"Buy insurance for losses you could not afford; self-insure small, affordable losses.","example":"","watch":"","kind":"principle"},{"id":"insurance-card-x5","skillId":"insurance-skill-02","front":"Summary of Benefits and Coverage","back":"Deductible, copays, coinsurance, out-of-pocket max, network rules, and example costs.","example":"","watch":"","kind":"document"},{"id":"insurance-card-x6","skillId":"insurance-skill-04","front":"Liability limits 50/100/50","back":"$50,000 per person injured, $100,000 per accident for injuries, $50,000 property damage.","example":"","watch":"","kind":"document"}]},"college":{"unit":"College & Career ROI","cards":[{"id":"college-card-1","skillId":"college-skill-01","front":"Cost of attendance (COA)","back":"The total estimated yearly cost of college: tuition, fees, housing, food, books, transportation, and personal expenses","example":"Tuition $12,400 + housing/food $13,800 + other $4,300 = $30,500 COA.","watch":""},{"id":"college-card-2","skillId":"college-skill-01","front":"Sticker price","back":"The published cost of attendance before any financial aid","example":"A private college listed at $68,000 per year.","watch":""},{"id":"college-card-3","skillId":"college-skill-01","front":"Net price","back":"Cost of attendance minus grants and scholarships — what the family must actually pay or borrow","example":"$30,500 − $11,000 in grants = $19,500.","watch":"Loans and work-study are not subtracted to find net price; loans must be repaid."},{"id":"college-card-4","skillId":"college-skill-01","front":"Grant","back":"Financial aid, usually need-based, that does not have to be repaid","example":"A federal Pell Grant.","watch":""},{"id":"college-card-5","skillId":"college-skill-01","front":"Scholarship","back":"Gift aid, often merit-based, that does not have to be repaid","example":"A $4,000 academic scholarship renewable with a 3.0 GPA.","watch":""},{"id":"college-card-6","skillId":"college-skill-01","front":"Work-study","back":"A financial aid program that provides part-time jobs to help students earn money for college costs","example":"$2,500 earned working at the campus library.","watch":""},{"id":"college-card-7","skillId":"college-skill-02","front":"Subsidized loan","back":"A federal student loan for which the government pays the interest while the student is enrolled at least half-time","example":"A $3,500 Direct Subsidized Loan for a first-year student.","watch":""},{"id":"college-card-8","skillId":"college-skill-02","front":"Unsubsidized loan","back":"A student loan that accrues interest from the time it is disbursed, including during school","example":"Interest builds while in school unless paid.","watch":""},{"id":"college-card-9","skillId":"college-skill-02","front":"Capitalized interest","back":"Unpaid interest that is added to the loan principal, so future interest is charged on it","example":"$1,400 of in-school interest added to a $10,000 balance.","watch":""},{"id":"college-card-10","skillId":"college-skill-01","front":"FAFSA","back":"The Free Application for Federal Student Aid, used to determine eligibility for federal grants, loans, and work-study","example":"Completing the FAFSA in senior year.","watch":""},{"id":"college-card-11","skillId":"college-skill-04","front":"Return on investment (ROI)","back":"The gain from an investment compared with its cost, often expressed as a percent or a payback period","example":"Earning $18,000 more per year after a $54,000 program.","watch":""},{"id":"college-card-12","skillId":"college-skill-04","front":"Payback period","back":"The time needed for extra earnings to cover the cost of an investment","example":"$54,000 ÷ $18,000 per year = 3 years.","watch":""},{"id":"college-card-13","skillId":"college-skill-03","front":"Opportunity cost of education","back":"Earnings given up while in school instead of working full-time","example":"Four years at $32,000 per year = $128,000 of forgone earnings.","watch":""},{"id":"college-card-14","skillId":"college-skill-03","front":"Apprenticeship","back":"A paid training program combining on-the-job learning with instruction, leading to a credential","example":"A 4-year electrician apprenticeship with rising pay.","watch":""},{"id":"college-card-15","skillId":"college-skill-03","front":"Lifetime earnings","back":"The total income earned over a working career","example":"Summing yearly salaries from age 22 to 65.","watch":""},{"id":"college-card-16","skillId":"college-skill-04","front":"Completion rate","back":"The share of students who finish a program within a set time","example":"A 60% six-year graduation rate means many students borrow without finishing.","watch":""},{"id":"college-card-x1","skillId":"college-skill-01","front":"Net price","back":"Cost of attendance − grants − scholarships (loans do not reduce it)","example":"","watch":"","kind":"formula"},{"id":"college-card-x2","skillId":"college-skill-02","front":"Debt guideline","back":"Try to keep total student debt at or below your expected first-year salary.","example":"","watch":"","kind":"principle"},{"id":"college-card-x3","skillId":"college-skill-04","front":"Payback period","back":"Total cost (including forgone earnings) ÷ extra yearly earnings","example":"","watch":"","kind":"formula"},{"id":"college-card-x4","skillId":"college-skill-01","front":"Reading an aid offer","back":"Separate gift aid (grants, scholarships), earned aid (work-study), and loans (student vs. parent).","example":"","watch":"","kind":"document"},{"id":"college-card-x5","skillId":"college-skill-03","front":"Opportunity cost of school","back":"Years in school are years without full-time pay — include forgone earnings in ROI.","example":"","watch":"","kind":"relationship"},{"id":"college-card-x6","skillId":"college-skill-02","front":"Subsidized vs. unsubsidized","back":"Subsidized: government pays interest in school. Unsubsidized: interest accrues and may capitalize.","example":"","watch":"","kind":"relationship"}]},"retirement":{"unit":"Retirement & Inflation","cards":[{"id":"retirement-card-1","skillId":"retirement-skill-01","front":"Inflation","back":"A general rise in prices over time, which reduces what each dollar can buy","example":"3% inflation turns a $100 grocery bill into about $103 next year.","watch":""},{"id":"retirement-card-2","skillId":"retirement-skill-01","front":"Consumer Price Index (CPI)","back":"A government measure of the average change in prices paid by consumers for a basket of goods and services","example":"If CPI rises from 300 to 309, prices rose 3%.","watch":""},{"id":"retirement-card-3","skillId":"retirement-skill-04","front":"Purchasing power","back":"The amount of goods and services a sum of money can buy","example":"$1,000 in 20 years at 3% inflation buys what about $554 buys today.","watch":""},{"id":"retirement-card-4","skillId":"retirement-skill-04","front":"Real value (today’s dollars)","back":"A future amount converted into what it would buy at today’s prices","example":"$1,000,000 in 40 years at 2.5% inflation ≈ $372,000 today.","watch":""},{"id":"retirement-card-5","skillId":"retirement-skill-04","front":"Nominal value","back":"An amount in the dollars of the time, not adjusted for inflation","example":"A $4.00 price in 2040 dollars.","watch":""},{"id":"retirement-card-6","skillId":"retirement-skill-03","front":"401(k)","back":"An employer-sponsored retirement savings plan funded by payroll contributions, often with an employer match","example":"Contributing 6% of each paycheck.","watch":""},{"id":"retirement-card-7","skillId":"retirement-skill-03","front":"Employer match","back":"Money an employer contributes based on the employee’s own contributions, up to a limit","example":"50% match on contributions up to 6% of salary.","watch":""},{"id":"retirement-card-8","skillId":"retirement-skill-03","front":"Vesting","back":"The schedule by which an employee gains full ownership of employer contributions","example":"Match fully owned after 3 years of service.","watch":""},{"id":"retirement-card-9","skillId":"retirement-skill-03","front":"Traditional (pre-tax) account","back":"A retirement account funded with pre-tax dollars; withdrawals in retirement are taxed","example":"Traditional 401(k) or IRA.","watch":""},{"id":"retirement-card-10","skillId":"retirement-skill-03","front":"Roth account","back":"A retirement account funded with after-tax dollars; qualified withdrawals in retirement are tax-free","example":"Roth IRA contributions from a summer job.","watch":""},{"id":"retirement-card-11","skillId":"retirement-skill-03","front":"IRA","back":"An Individual Retirement Account opened by a person rather than through an employer","example":"Opening a Roth IRA at a brokerage.","watch":""},{"id":"retirement-card-12","skillId":"retirement-skill-02","front":"Nest egg","back":"The total savings accumulated for retirement","example":"A goal of $900,000 by age 67.","watch":""},{"id":"retirement-card-13","skillId":"retirement-skill-02","front":"4% guideline","back":"A planning rule of thumb that withdrawing about 4% of savings in the first year of retirement (adjusted for inflation after) may last about 30 years","example":"$800,000 × 4% = $32,000 first-year withdrawal.","watch":"It is a guideline based on historical studies, not a guarantee."},{"id":"retirement-card-14","skillId":"retirement-skill-02","front":"Social Security","back":"A federal program funded by payroll taxes that provides retirement, disability, and survivor benefits","example":"A monthly benefit beginning at age 62–70.","watch":""},{"id":"retirement-card-15","skillId":"retirement-skill-04","front":"Real rate of return","back":"A return adjusted for inflation: (1 + nominal) ÷ (1 + inflation) − 1","example":"6% nominal and 2.5% inflation → about 3.4% real.","watch":""},{"id":"retirement-card-x1","skillId":"retirement-skill-01","front":"Future price","back":"price × (1 + inflation)^years","example":"","watch":"","kind":"formula"},{"id":"retirement-card-x2","skillId":"retirement-skill-04","front":"Today’s dollars","back":"future amount ÷ (1 + inflation)^years","example":"","watch":"","kind":"formula"},{"id":"retirement-card-x3","skillId":"retirement-skill-04","front":"Real return","back":"(1 + nominal) ÷ (1 + inflation) − 1","example":"","watch":"","kind":"formula"},{"id":"retirement-card-x4","skillId":"retirement-skill-03","front":"Always get the full match","back":"Contribute at least enough to receive the entire employer match — it is part of your pay.","example":"","watch":"","kind":"principle"},{"id":"retirement-card-x5","skillId":"retirement-skill-03","front":"Traditional vs. Roth","back":"Traditional: tax break now, taxed later. Roth: taxed now, tax-free later. Choose based on expected tax rates.","example":"","watch":"","kind":"relationship"},{"id":"retirement-card-x6","skillId":"retirement-skill-02","front":"Nest egg (4% guideline)","back":"(yearly spending − other income) ÷ 0.04","example":"","watch":"","kind":"formula"}]}};
